from dataclasses import dataclass, field
import datetime as _dt
from typing import List, Optional, Tuple


@dataclass
class Account:
    path: str
    type: str
    currency: Optional[str] = None
    opened: Optional[_dt.date] = None
    closed: Optional[_dt.date] = None
    note: str = ""


@dataclass(frozen=True)
class Posting:
    account: str
    amount: object  # Money or None
    note: str = ""


@dataclass
class Transaction:
