"""The ledger: validated transactions and balances."""
import re

from tallybook._util import is_date, is_int
from tallybook.accounts import Chart
from tallybook.currency import RateTable
from tallybook.dates import format_date
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, format_minor

TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


class LedgerError(ValidationError):
    """A transaction the ledger refuses."""


def _has_break(text):
    return "\n" in text or "\r" in text


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._next_id = 1

    def __len__(self):
        return len(self._txs)

    # -- validation -------------------------------------------------------
    def _check(self, tx, keep_id=None):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a Transaction: %r" % (tx,))
        if not is_date(tx.date):
            raise LedgerError("transaction date must be a datetime.date, got %r" % (tx.date,))
        if tx.flag not in ("*", "!"):
            raise LedgerError("invalid flag %r: expected * or !" % (tx.flag,))
        for name in ("payee", "narration"):
            value = getattr(tx, name)
            if not isinstance(value, str):
                raise LedgerError("%s must be text" % name)
            if _has_break(value):
                raise LedgerError("%s must not contain a line break" % name)
        tags = tx.tags
        if isinstance(tags, str) or tags is None:
            raise LedgerError("tags must be a tuple of tag names")
        try:
            tags = list(tags)
        except TypeError:
            raise LedgerError("tags must be a tuple of tag names") from None
        for t in tags:
            if not isinstance(t, str) or not TAG_RE.fullmatch(t):
                raise LedgerError("invalid tag %r" % (t,))
        tags = tuple(sorted(set(tags)))
        try:
            postings = list(tx.postings)
        except TypeError:
            raise LedgerError("postings must be a list") from None
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a Posting: %r" % (p,))
            if not isinstance(p.note, str):
                raise LedgerError("posting note must be text")
            if _has_break(p.note):
                raise LedgerError("posting note must not contain a line break")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("posting amount must be Money or None, got %r" % (p.amount,))
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        day = format_date(tx.date)
        for p in postings:
            if not isinstance(p.account, str) or not self.chart.exists(p.account):
                raise LedgerError("unknown account %s" % (p.account,))
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, day))
        missing = [i for i, p in enumerate(postings) if p.amount is None]
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = {}
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        off = sorted(c for c, v in sums.items() if v != 0)
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            i = missing[0]
            p = postings[i]
            filled = [Posting(p.account, Money(-sums[c], c), p.note) for c in off]
            postings = postings[:i] + filled + postings[i + 1:]
        elif off:
            raise LedgerError("transaction does not balance: "
                              + ", ".join("%s %s" % (c, format_minor(sums[c], c)) for c in off))
        for p in postings:
            acc = self.chart.get(p.account)
            if acc.currency is not None and p.amount.currency != acc.currency:
                raise LedgerError("account %s only holds %s, not %s"
                                  % (p.account, acc.currency, p.amount.currency))
        if keep_id is not None:
            if tx.id is not None and tx.id != keep_id:
                raise LedgerError("transaction id %r does not match %d" % (tx.id, keep_id))
            new_id = keep_id
        elif tx.id is None:
            new_id = self._next_id
        else:
            if not is_int(tx.id) or tx.id < 1:
                raise LedgerError("invalid transaction id %r" % (tx.id,))
            if tx.id in self._txs:
                raise LedgerError("transaction %d already exists" % tx.id)
            new_id = tx.id
        return Transaction(tx.date, tx.payee, tx.narration, postings, tags, tx.flag, new_id)

    # -- changing ---------------------------------------------------------
    def add(self, tx):
        stored = self._check(tx)
        self._txs[stored.id] = stored
        self._next_id = max(self._next_id, stored.id + 1)
        return stored

    def add_many(self, transactions):
        saved = (dict(self._txs), self._next_id)
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs, self._next_id = saved
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %r" % (id,))
        stored = self._check(tx, keep_id=id)
        self._txs[id] = stored
        return stored

    def get(self, id):
        try:
            return self._txs[id]
        except (KeyError, TypeError):
            raise NotFoundError("no transaction %r" % (id,)) from None

    def remove(self, id):
        tx = self.get(id)
        del self._txs[id]
        return tx

    # -- reading ----------------------------------------------------------
    def transactions(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def postings(self):
        for tx in self.transactions():
            for p in tx.postings:
                yield tx, p

    def balances(self, as_of=None):
        out = {}
        for tx, p in self.postings():
            if as_of is not None and tx.date > as_of:
                continue
            acc = out.setdefault(p.account, {})
            acc[p.amount.currency] = acc.get(p.amount.currency, 0) + p.amount.minor
        return _clean(out)

    def rollup_balances(self, as_of=None):
        out = {}
        for tx, p in self.postings():
            if as_of is not None and tx.date > as_of:
                continue
            segs = p.account.split(":")
            for i in range(1, len(segs) + 1):
                acc = out.setdefault(":".join(segs[:i]), {})
                acc[p.amount.currency] = acc.get(p.amount.currency, 0) + p.amount.minor
        return _clean(out)

    def balance(self, account, as_of=None, currency=None, rollup=True):
        self.chart.get(account)
        sums = {}
        for tx, p in self.postings():
            if as_of is not None and tx.date > as_of:
                continue
            if p.account == account or (rollup and p.account.startswith(account + ":")):
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        if currency is not None:
            return Money(sums.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in sorted(sums.items()) if v != 0}


def _clean(out):
    result = {}
    for acc in sorted(out):
        cur = {c: v for c, v in sorted(out[acc].items()) if v != 0}
        if cur:
            result[acc] = cur
    return result
"""tallybook: double-entry bookkeeping, standard library only."""

__version__ = "1.0.0"

"""Exact money: whole minor units plus a currency code."""
import re

from tallybook._util import is_int
from tallybook.currency import CURRENCIES, CurrencyError, currency as _currency
from tallybook.errors import ValidationError


class MoneyError(ValidationError):
    """A bad amount or an operation mixing currencies."""


def round_div(n, d):
    """n / d rounded to the nearest integer, halves away from zero."""
    if not is_int(n) or not is_int(d):
        raise MoneyError("round_div needs integers, got %r and %r" % (n, d))
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, got %r" % (d,))
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


def _exponent(code):
    return _currency(code).exponent


def format_minor(minor, currency):
    """The amount text of a number of minor units: -5 USD -> '-0.05'."""
    e = _exponent(currency)
    if not is_int(minor):
        raise MoneyError("amount must be an integer number of minor units, got %r" % (minor,))
    sign = "-" if minor < 0 else ""
    digits = str(abs(minor))
    if e == 0:
        return sign + digits
    digits = digits.rjust(e + 1, "0")
    return sign + digits[:-e] + "." + digits[-e:]


_AMOUNT_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def parse_amount(text, currency):
    """Read an amount typed by hand and return its minor units as an int."""
    e = _exponent(currency)
    if not isinstance(text, str):
        raise MoneyError("invalid amount %r: not text" % (text,))
    m = _AMOUNT_RE.fullmatch(text)
    if not m:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.groups()
    if frac is not None:
        if e == 0:
            raise MoneyError("invalid amount '%s': %s has no decimals" % (text, currency))
        if len(frac) > e:
            raise MoneyError("invalid amount '%s': %s has only %d decimals" % (text, currency, e))
    else:
        frac = ""
    value = int(whole + frac.ljust(e, "0"))
    return -value if sign == "-" else value


class Money:
    """An immutable amount of one currency, in minor units."""

    __slots__ = ("_minor", "_currency")

    def __init__(self, minor, currency):
        if not is_int(minor):
            raise MoneyError("amount must be an integer number of minor units, got %r" % (minor,))
        _currency(currency)
        object.__setattr__(self, "_minor", int(minor))
        object.__setattr__(self, "_currency", currency)

    def __setattr__(self, name, value):
        raise AttributeError("Money is immutable")

    def __delattr__(self, name):
        raise AttributeError("Money is immutable")

    def __reduce__(self):
        return (Money, (self._minor, self._currency))

    @property
    def minor(self):
        return self._minor

    @property
    def currency(self):
        return self._currency

    @property
    def exponent(self):
        return CURRENCIES[self._currency].exponent

    @classmethod
    def zero(cls, currency):
        return cls(0, currency)

    @classmethod
    def of(cls, text, currency):
        return cls(parse_amount(text, currency), currency)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise MoneyError("invalid money %r: not text" % (text,))
        parts = text.split(" ")
        if len(parts) != 2 or not parts[0] or not parts[1]:
            raise MoneyError("invalid money '%s': expected 'AMOUNT CUR'" % text)
        amount, code = parts
        _currency(code)
        return cls(parse_amount(amount, code), code)

    def amount_str(self):
        return format_minor(self._minor, self._currency)

    def __str__(self):
        return "%s %s" % (self.amount_str(), self._currency)

    def __repr__(self):
        return "Money(%d, '%s')" % (self._minor, self._currency)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self._minor == other._minor and self._currency == other._currency

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self._minor, self._currency))

    def _same(self, other, verb):
        if not isinstance(other, Money):
            raise TypeError("cannot %s Money and %s" % (verb, type(other).__name__))
        if other._currency != self._currency:
            raise MoneyError("cannot %s %s and %s: different currencies"
                             % (verb, self._currency, other._currency))

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "add")
        return Money(self._minor + other._minor, self._currency)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "subtract")
        return Money(self._minor - other._minor, self._currency)

    def __neg__(self):
        return Money(-self._minor, self._currency)

    def __pos__(self):
        return self

    def __abs__(self):
        return Money(abs(self._minor), self._currency)

    def __mul__(self, other):
        if not is_int(other):
            return NotImplemented
        return Money(self._minor * other, self._currency)

    __rmul__ = __mul__

    def __lt__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "compare")
        return self._minor < other._minor

    def __le__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "compare")
        return self._minor <= other._minor

    def __gt__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "compare")
        return self._minor > other._minor

    def __ge__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "compare")
        return self._minor >= other._minor

    def __bool__(self):
        return self._minor != 0

    def is_zero(self):
        return self._minor == 0

    def sign(self):
        return (self._minor > 0) - (self._minor < 0)

    def scale(self, num, den=1):
        if not is_int(num) or not is_int(den):
            raise MoneyError("scale needs integers, got %r and %r" % (num, den))
        if den == 0:
            raise MoneyError("scale by a ratio with zero denominator")
        if den < 0:
            num, den = -num, -den
        return Money(round_div(self._minor * num, den), self._currency)

    def allocate(self, weights):
        if not isinstance(weights, (list, tuple)):
            raise MoneyError("weights must be a list of integers")
        weights = list(weights)
        if not weights:
            raise MoneyError("weights must not be empty")
        for w in weights:
            if not is_int(w):
                raise MoneyError("weight %r is not an integer" % (w,))
            if w < 0:
                raise MoneyError("weight %r is negative" % (w,))
        total = sum(weights)
        if total <= 0:
            raise MoneyError("weights must not all be zero")
        amount = abs(self._minor)
        shares = []
        rems = []
        for w in weights:
            q, r = divmod(amount * w, total)
            shares.append(q)
            rems.append(r)
        left = amount - sum(shares)
        order = sorted(range(len(weights)), key=lambda i: (-rems[i], i))
        for i in order[:left]:
            shares[i] += 1
        neg = self._minor < 0
        return [Money(-s if neg else s, self._currency) for s in shares]


__all__ = ["Money", "MoneyError", "parse_amount", "format_minor", "round_div", "CurrencyError"]
"""The chart of accounts."""
import re

from tallybook._util import is_date
from tallybook.currency import is_currency
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Account


class ChartError(ValidationError):
    """A malformed account, pattern or chart operation."""


ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = ("asset", "liability", "equity", "income", "expense")

_SEGMENT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def valid_segment(seg):
    return isinstance(seg, str) and _SEGMENT_RE.fullmatch(seg) is not None


def valid_path(text):
    if not isinstance(text, str) or not text:
        return False
    segs = text.split(":")
    if segs[0] not in ROOT_TYPES:
        return False
    return all(_SEGMENT_RE.fullmatch(s) for s in segs)


def _check_path(path):
    if not valid_path(path):
        raise ChartError("invalid account path %r" % (path,) if not isinstance(path, str)
                         else "invalid account path '%s'" % path)


def parent_path(path):
    _check_path(path)
    if ":" not in path:
        return None
    return path.rsplit(":", 1)[0]


def account_type(path):
    _check_path(path)
    return ROOT_TYPES[path.split(":", 1)[0]]


def path_key(path):
    return path.split(":")


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern %r" % (pattern,))
    segs = pattern.split(":")
    for s in segs:
        if s in ("*", "**"):
            continue
        if not _SEGMENT_RE.fullmatch(s):
            raise ChartError("invalid account pattern '%s'" % pattern)
    return segs


def _match_segs(pat, segs):
    if not pat:
        return not segs
    head = pat[0]
    if head == "**":
        for k in range(1, len(segs) + 1):
            if _match_segs(pat[1:], segs[k:]):
                return True
        return False
    if not segs:
        return False
    if head == "*" or head == segs[0]:
        return _match_segs(pat[1:], segs[1:])
    return False


def path_matches(pattern, path):
    pat = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    if "*" not in pat and "**" not in pat:
        return path == pattern or path.startswith(pattern + ":")
    return _match_segs(pat, path.split(":"))


class Chart:
    def __init__(self):
        self._accounts = {}
        self._explicit = set()

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _check_path(path)
        root_type = account_type(path)
        if type is not None:
            if type not in TYPES:
                raise ChartError("invalid account type %r" % (type,))
            if type != root_type:
                raise ChartError("account %s must have type %s, not %s" % (path, root_type, type))
        if currency is not None and not is_currency(currency):
            raise ChartError("unknown currency %r" % (currency,))
        if opened is not None and not is_date(opened):
            raise ChartError("invalid opening date %r" % (opened,))
        if not isinstance(note, str):
            raise ChartError("note must be text")
        if path in self._explicit:
            raise ChartError("account %s already exists" % path, code="conflict")
        segs = path.split(":")
        for i in range(1, len(segs)):
            parent = ":".join(segs[:i])
            if parent not in self._accounts:
                self._accounts[parent] = Account(parent, ROOT_TYPES[segs[0]])
        acc = self._accounts.get(path)
        if acc is None:
            acc = Account(path, root_type, currency, opened, None, note)
            self._accounts[path] = acc
        else:
            acc.currency = currency
            acc.opened = opened
            acc.note = note
        self._explicit.add(path)
        return acc

    def is_explicit(self, path):
        return path in self._explicit

    def get(self, path):
        if not isinstance(path, str) or path not in self._accounts:
            raise NotFoundError("no such account: %s" % (path,))
        return self._accounts[path]

    def exists(self, path):
        return isinstance(path, str) and path in self._accounts

    def __contains__(self, path):
        return self.exists(path)

    def __len__(self):
        return len(self._accounts)

    def accounts(self):
        return [self._accounts[p] for p in sorted(self._accounts, key=path_key)]

    def children(self, path):
        self.get(path)
        n = path.count(":") + 1
        return [a for a in self.accounts()
                if a.path.startswith(path + ":") and a.path.count(":") == n]

    def descendants(self, path):
        self.get(path)
        return [a for a in self.accounts() if a.path.startswith(path + ":")]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        acc = self.get(path)
        if acc.opened is not None and on < acc.opened:
            return False
        if acc.closed is not None and on > acc.closed:
            return False
        return True

    def close(self, path, on):
        acc = self.get(path)
        if not is_date(on):
            raise ChartError("invalid closing date %r" % (on,))
        if acc.closed is not None:
            raise ChartError("account %s is already closed" % path)
        if acc.opened is not None and on < acc.opened:
            raise ChartError("account %s cannot be closed before it was opened" % path)
        acc.closed = on
        return acc

    def matches(self, pattern):
        _check_pattern(pattern)
        return [a for a in self.accounts() if path_matches(pattern, a.path)]
"""Dates, months and periods; strict YYYY-MM-DD everywhere."""
import datetime as _dt
import re

from tallybook._util import is_date, is_int
from tallybook.errors import ParseError


class DateError(ParseError):
    """A malformed date or period, or a date outside the calendar."""


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def _show(text):
    return "'%s'" % text if isinstance(text, str) else repr(text)


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date %r: expected text YYYY-MM-DD" % (text,))
    m = _DATE_RE.fullmatch(text)
    if not m:
        raise DateError("invalid date '%s': expected YYYY-MM-DD" % text)
    try:
        return _dt.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date '%s': no such day" % text) from None


def format_date(d):
    if not is_date(d):
        raise DateError("not a date: %r" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not is_int(year) or not is_int(month):
        raise DateError("year and month must be integers, got %r and %r" % (year, month))
    if not 1 <= month <= 12:
        raise DateError("invalid month %d" % month)
    if not 1 <= year <= 9999:
        raise DateError("invalid year %d" % year)
    if month == 12:
        return 31
    return (_dt.date(year, month + 1, 1) - _dt.timedelta(days=1)).day


def add_months(d, n):
    if not is_date(d):
        raise DateError("not a date: %r" % (d,))
    if not is_int(n):
        raise DateError("number of months must be an integer, got %r" % (n,))
    index = d.year * 12 + (d.month - 1) + n
    year, month0 = divmod(index, 12)
    if not 1 <= year <= 9999:
        raise DateError("date out of range: %s moved by %d months" % (format_date(d), n))
    month = month0 + 1
    return _dt.date(year, month, min(d.day, last_day(year, month)))


def _add_days(d, n):
    try:
        return d + _dt.timedelta(days=n)
    except OverflowError:
        raise DateError("date out of range") from None


class Period:
    """A run of whole days, both ends included."""

    __slots__ = ("_start", "_end")

    def __init__(self, start, end):
        if not is_date(start) or not is_date(end):
            raise DateError("period needs two dates, got %r and %r" % (start, end))
        if end < start:
            raise DateError("empty period: %s is before %s" % (format_date(end), format_date(start)))
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_end", end)

    def __setattr__(self, name, value):
        raise AttributeError("Period is immutable")

    @property
    def start(self):
        return self._start

    @property
    def end(self):
        return self._end

    def __eq__(self, other):
        if not isinstance(other, Period):
            return NotImplemented
        return self._start == other._start and self._end == other._end

    def __hash__(self):
        return hash((self._start, self._end))

    def __repr__(self):
        return "Period(%r, %r)" % (self._start, self._end)

    def __str__(self):
        return self.label

    def contains(self, d):
        if not is_date(d):
            raise DateError("not a date: %r" % (d,))
        return self._start <= d <= self._end

    @property
    def days(self):
        return (self._end - self._start).days + 1

    def _kind(self):
        s, e = self._start, self._end
        if s.day != 1:
            return None
        if e.day != last_day(e.year, e.month) or s.year != e.year:
            return None
        if s.month == 1 and e.month == 12:
            return "year"
        if s.month == e.month:
            return "month"
        if s.month % 3 == 1 and e.month == s.month + 2:
            return "quarter"
        return None

    @property
    def label(self):
        kind = self._kind()
        s = self._start
        if kind == "year":
            return "%04d" % s.year
        if kind == "month":
            return "%04d-%02d" % (s.year, s.month)
        if kind == "quarter":
            return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
        return "%s..%s" % (format_date(self._start), format_date(self._end))

    def next(self):
        kind = self._kind()
        s = self._start
        if kind in ("month", "quarter", "year"):
            months = {"month": 1, "quarter": 3, "year": 12}[kind]
            if s.year == 9999 and s.month + months > 12:
                raise DateError("no period after %s" % self.label)
            ns = add_months(s, months)
            ne = add_months(ns, months - 1)
            return Period(ns, _dt.date(ne.year, ne.month, last_day(ne.year, ne.month)))
        ns = _add_days(self._end, 1)
        return Period(ns, _add_days(ns, self.days - 1))

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise DateError("invalid period %r" % (text,))
        try:
            m = re.fullmatch(r"([0-9]{4})", text)
            if m:
                y = int(m.group(1))
                return cls(_dt.date(y, 1, 1), _dt.date(y, 12, 31))
            m = re.fullmatch(r"([0-9]{4})-([0-9]{2})", text)
            if m:
                y, mo = int(m.group(1)), int(m.group(2))
                return cls(_dt.date(y, mo, 1), _dt.date(y, mo, last_day(y, mo)))
            m = re.fullmatch(r"([0-9]{4})-Q([1-4])", text)
            if m:
                y, q = int(m.group(1)), int(m.group(2))
                mo = 3 * q - 2
                return cls(_dt.date(y, mo, 1), _dt.date(y, mo + 2, last_day(y, mo + 2)))
            m = re.fullmatch(r"([0-9]{4}-[0-9]{2}-[0-9]{2})\.\.([0-9]{4}-[0-9]{2}-[0-9]{2})", text)
            if m:
                return cls(parse_date(m.group(1)), parse_date(m.group(2)))
        except (ValueError, DateError):
            pass
        raise DateError("invalid period '%s': expected YYYY, YYYY-MM, YYYY-Qn or DATE..DATE" % text)


_STEPS = ("week", "month", "quarter", "year")


def _period_containing(d, step):
    if step == "week":
        s = _add_days(d, -d.weekday()) if d.toordinal() - d.weekday() >= 1 else _dt.date(1, 1, 1)
        return Period(s, _add_days(s, 6) if s.toordinal() + 6 <= _dt.date.max.toordinal()
                      else _dt.date.max)
    if step == "month":
        return Period(_dt.date(d.year, d.month, 1), _dt.date(d.year, d.month, last_day(d.year, d.month)))
    if step == "quarter":
        mo = (d.month - 1) // 3 * 3 + 1
        return Period(_dt.date(d.year, mo, 1), _dt.date(d.year, mo + 2, last_day(d.year, mo + 2)))
    return Period(_dt.date(d.year, 1, 1), _dt.date(d.year, 12, 31))


def periods(start, end, step):
    if step not in _STEPS:
        raise DateError("unknown step %r: expected week, month, quarter or year" % (step,))
    if not is_date(start) or not is_date(end):
        raise DateError("periods needs two dates, got %r and %r" % (start, end))
    if end < start:
        raise DateError("%s is before %s" % (format_date(end), format_date(start)))
    out = [_period_containing(start, step)]
    while out[-1].end < end:
        out.append(_period_containing(_add_days(out[-1].end, 1), step))
    return out
"""Currencies and exchange rates."""
import re
from dataclasses import dataclass
from fractions import Fraction

from tallybook._util import is_date
from tallybook.errors import ValidationError


class CurrencyError(ValidationError):
    """An unknown currency, a bad rate or a missing rate."""


@dataclass(frozen=True)
class Currency:
    code: str
    exponent: int
    name: str
    symbol: str


CURRENCIES = {
    c.code: c
    for c in [
        Currency("USD", 2, "US Dollar", "$"),
        Currency("EUR", 2, "Euro", "€"),
        Currency("GBP", 2, "British Pound", "£"),
        Currency("JPY", 0, "Japanese Yen", "¥"),
        Currency("CHF", 2, "Swiss Franc", "CHF"),
        Currency("CAD", 2, "Canadian Dollar", "CA$"),
        Currency("AUD", 2, "Australian Dollar", "A$"),
        Currency("KWD", 3, "Kuwaiti Dinar", "KD"),
        Currency("SEK", 2, "Swedish Krona", "kr"),
        Currency("INR", 2, "Indian Rupee", "₹"),
        Currency("NZD", 2, "New Zealand Dollar", "NZ$"),
        Currency("NOK", 2, "Norwegian Krone", "kr"),
        Currency("KRW", 0, "South Korean Won", "₩"),
        Currency("BHD", 3, "Bahraini Dinar", "BD"),
        Currency("CNY", 2, "Chinese Yuan", "CN¥"),
        Currency("MXN", 2, "Mexican Peso", "MX$"),
    ]
}


def is_currency(code):
    return isinstance(code, str) and code in CURRENCIES


def currency(code):
    """Return the Currency for a code, or raise CurrencyError."""
    if not is_currency(code):
        if isinstance(code, str):
            raise CurrencyError("unknown currency '%s'" % code)
        raise CurrencyError("unknown currency %r" % (code,))
    return CURRENCIES[code]


_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")


def parse_rate_text(text):
    """Check a rate text and return it as an exact Fraction (CurrencyError if bad)."""
    if not isinstance(text, str) or not _RATE_RE.fullmatch(text):
        raise CurrencyError("invalid rate %r" % (text,) if not isinstance(text, str)
                            else "invalid rate '%s'" % text)
    value = Fraction(text)
    if value <= 0:
        raise CurrencyError("invalid rate '%s': must be positive" % text)
    return value


def _check_date(on):
    if not is_date(on):
        raise CurrencyError("invalid date %r: expected a datetime.date" % (on,))


def _fmt(d):
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


class RateTable:
    """Exchange rates by day; one unit of src buys rate units of dst."""

    def __init__(self):
        self._rates = {}  # (src, dst) -> {date: Fraction}

    def set(self, src, dst, rate_text, on):
        currency(src)
        currency(dst)
        if src == dst:
            raise CurrencyError("cannot set a rate from %s to itself" % src)
        value = parse_rate_text(rate_text)
        _check_date(on)
        self._rates.setdefault((src, dst), {})[on] = value

    def _latest(self, src, dst, on):
        table = self._rates.get((src, dst))
        if not table:
            return None
        best = None
        for d in table:
            if d <= on and (best is None or d > best):
                best = d
        return None if best is None else table[best]

    def rate(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        if src == dst:
            return Fraction(1)
        direct = self._latest(src, dst, on)
        if direct is not None:
            return direct
        inverse = self._latest(dst, src, on)
        if inverse is not None:
            return 1 / inverse
        raise CurrencyError("no rate %s -> %s on %s" % (src, dst, _fmt(on)))

    def convert(self, money, dst, on):
        from tallybook.money import Money, round_div

        if not isinstance(money, Money):
            raise CurrencyError("cannot convert %r: not a Money" % (money,))
        currency(dst)
        _check_date(on)
        if money.currency == dst:
            return money
        r = self.rate(money.currency, dst, on)
        diff = CURRENCIES[dst].exponent - CURRENCIES[money.currency].exponent
        num = money.minor * r.numerator
        den = r.denominator
        if diff >= 0:
            num *= 10 ** diff
        else:
            den *= 10 ** (-diff)
        return Money(round_div(num, den), dst)

    def entries(self):
        out = []
        for (src, dst), table in self._rates.items():
            for d, value in table.items():
                out.append((src, dst, d, value))
        out.sort(key=lambda e: (e[0], e[1], e[2]))
        return out

    def remove(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        table = self._rates.get((src, dst))
        if not table or on not in table:
            raise CurrencyError("no rate %s -> %s set on %s" % (src, dst, _fmt(on)))
        del table[on]
        if not table:
            del self._rates[(src, dst)]

    def copy(self):
        new = RateTable()
        new._rates = {k: dict(v) for k, v in self._rates.items()}
        return new

