"""The journal file: a whole book as one readable text file."""
import re
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import ROOT_TYPES, valid_path
from tallybook.currency import CurrencyError, is_currency, parse_rate_text
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ParseError, TallybookError
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money, parse_amount

__all__ = ["Journal", "JournalError", "parse_journal", "format_journal", "format_transaction"]

_TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")
_BLANKS = " \t"


class JournalError(ParseError):
    """A mistake in the writing of a journal file; ``.line`` is 1-based."""

    def __init__(self, line, description=""):
        self.line = line
        self.description = description
        super().__init__("line %d: %s" % (line, description))


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: list = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def to_ledger(self):
        ledger = Ledger()
        for acc in self.accounts:
            ledger.chart.add(acc.path, type=acc.type, currency=acc.currency,
                             opened=acc.opened, note=acc.note)
            if acc.closed is not None:
                ledger.chart.close(acc.path, acc.closed)
        for src, dst, on, rate_text in self.rates:
            ledger.rates.set(src, dst, rate_text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


# -- reading -------------------------------------------------------------

class _Mistake(Exception):
    pass


def _tokenize(line):
    """Split a line into tokens ('w', text) / ('q', text) and a comment (or None)."""
    tokens = []
    comment = None
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in _BLANKS:
            i += 1
            continue
        if c == ";":
            comment = line[i + 1:]
            break
        if c == '"':
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise _Mistake("missing closing quote")
                c = line[i]
                if c == "\\":
                    if i + 1 < n and line[i + 1] in '"\\':
                        buf.append(line[i + 1])
                        i += 2
                        continue
                    raise _Mistake("invalid backslash escape in quoted string")
                if c == '"':
                    i += 1
                    break
                buf.append(c)
                i += 1
            if i < n and line[i] not in _BLANKS and line[i] != ";":
                raise _Mistake("unexpected text after closing quote")
            tokens.append(("q", "".join(buf)))
            continue
        j = i
        while j < n and line[j] not in _BLANKS and line[j] != ";":
            if line[j] == '"':
                raise _Mistake("unexpected quote")
            j += 1
        tokens.append(("w", line[i:j]))
        i = j
    return tokens, comment


def _date(text):
    try:
        return parse_date(text)
    except DateError:
