    tags = set()
    for kind, value in tokens[k:]:
        if kind != "w" or not value.startswith("#") or not _TAG_RE.fullmatch(value[1:]):
            raise _Mistake("unexpected %s on transaction line"
                           % ("'%s'" % value if kind == "w" else "quoted string"))
        tags.add(value[1:])
