    if not tokens:
        raise _Mistake("missing account on posting line")
    account = _path(_word(tokens, 0, "account"))
    amount = None
    if len(tokens) == 2:
        raise _Mistake("an amount needs a currency")
    if len(tokens) > 3:
        raise _Mistake("unexpected text after the amount")
    if len(tokens) == 3:
        amount_text = _word(tokens, 1, "amount")
        code = _currency(_word(tokens, 2, "currency"))
        try:
            amount = Money(parse_amount(amount_text, code), code)
        except TallybookError as e:
            raise _Mistake(e.message) from None
    note = comment.strip(_BLANKS) if comment is not None else ""
    return Posting(account, amount, note)


def parse_journal(text):
    if not isinstance(text, str):
        raise JournalError(1, "journal text must be a string")
    if text.startswith("\ufeff"):
        text = text[1:]
    if text == "":
        return Journal()
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    journal = Journal()
    seen = set()
    current = None
    for number, line in enumerate(lines, 1):
        if line.endswith("\r"):
            line = line[:-1]
        stripped = line.lstrip(_BLANKS)
        if stripped == "":
            current = None
            continue
        if stripped[0] in ";#":
            continue
        try:
            if line[0] in _BLANKS:
                if current is None:
                    raise _Mistake("indented line outside a transaction")
                tokens, comment = _tokenize(line)
                current.postings.append(_parse_posting(tokens, comment))
                continue
            current = None
            tokens, _ = _tokenize(line)
            first = tokens[0]
            if first == ("w", "account"):
                acc = _parse_account(tokens)
                if acc.path in seen:
                    raise _Mistake("account %s is declared twice" % acc.path)
                seen.add(acc.path)
