import re
from fractions import Fraction

from tallybook.currency import CURRENCIES
from tallybook.dates import DateError, Period, parse_date
from tallybook.errors import ParseError

__all__ = ["parse_query", "select", "Query", "QueryError"]


class QueryError(ParseError):
    """Query text that cannot be understood; ``.position`` is 1-based."""

    def __init__(self, description, position):
        self.position = position
        self.description = description
        super().__init__("%s at position %d" % (description, position))


_SPACE = " "
_ENDERS = " ()"
_NAME_RE = re.compile(r"[A-Za-z]+")
_OPS = ("<=", ">=", "!=", "<", ">", "=")
_TEXT_NAMES = ("payee", "narration", "tag", "date", "flag", "id", "account")
_CMP_NAMES = ("date", "amount")
_PART_RE = re.compile(r"[A-Za-z0-9_-]+")
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_KEYWORDS = ("and", "or", "not")


def _is_space(c):
    return c == " " or c == "\t"


def _compare(op, a, b):
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    if op == "=":
        return a == b
    return a != b


# -- expression nodes ----------------------------------------------------

class _Node:
    def eval(self, tx, posting):  # pragma: no cover - abstract
        raise NotImplementedError


class _And(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, p):
        return self.left.eval(tx, p) and self.right.eval(tx, p)


class _Or(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, p):
        return self.left.eval(tx, p) or self.right.eval(tx, p)


class _Not(_Node):
    def __init__(self, inner):
        self.inner = inner

    def eval(self, tx, p):
        return not self.inner.eval(tx, p)


class _Func(_Node):
    def __init__(self, fn):
        self.fn = fn

    def eval(self, tx, p):
        return bool(self.fn(tx, p))


def _contains(hay, needle):
    return isinstance(hay, str) and needle in hay.lower()


def _split_pattern(value):
    parts = value.split(":")
    for part in parts:
        if part in ("*", "**"):
            continue
        if not _PART_RE.fullmatch(part):
            return None
    return parts


def _prefix_match(pat, segs):
    """True when pat matches segs[:k] for some k (the account may go on below)."""
    if not pat:
        return True
    head, rest = pat[0], pat[1:]
    if head == "**":
        return any(_prefix_match(rest, segs[k:]) for k in range(len(segs) + 1))
    if not segs:
        return False
    if head == "*" or head == segs[0]:
        return _prefix_match(rest, segs[1:])
    return False


def _account_matches(parts, path):
    return isinstance(path, str) and _prefix_match(parts, path.split(":"))


def _posting_value(p):
    amount = getattr(p, "amount", None)
    if amount is None:
        return None
    return Fraction(amount.minor, 10 ** CURRENCIES[amount.currency].exponent)


# -- tokens --------------------------------------------------------------

class _Lexer:
    def __init__(self, text, chart):
        self.text = text
        self.chart = chart
        self.i = 0
        self.n = len(text)

    def _quoted(self, start):
        """Read a quoted string whose opening quote is at start; return (text, end)."""
        text, n = self.text, self.n
        i = start + 1
        buf = []
        while True:
            if i >= n:
                raise QueryError("unterminated quote", start + 1)
            c = text[i]
            if c == "\\" and i + 1 < n and text[i + 1] in '"\\':
                buf.append(text[i + 1])
                i += 2
                continue
            if c == '"':
                i += 1
                break
            buf.append(c)
            i += 1
        if i < n and text[i] not in _ENDERS and not _is_space(text[i]):
            raise QueryError("unexpected text after closing quote", i + 1)
        return "".join(buf), i

    def _run(self, i):
        j = i
        while j < self.n and self.text[j] not in _ENDERS and not _is_space(self.text[j]):
            j += 1
        return j

    def next(self):
        """Return the next token: (kind, value, position) with kind in LP RP KW TERM END."""
        text, n = self.text, self.n
        while self.i < n and _is_space(text[self.i]):
            self.i += 1
        i = self.i
        if i >= n:
            return ("END", None, n + 1)
        c = text[i]
        pos = i + 1
        if c == "(":
            self.i = i + 1
            return ("LP", None, pos)
        if c == ")":
            self.i = i + 1
            return ("RP", None, pos)
        if c == '"':
            value, end = self._quoted(i)
            self.i = end
            if value == "":
                raise QueryError("empty quotes", pos)
            return ("TERM", self._text_term(value), pos)
        m = _NAME_RE.match(text, i)
        if m:
            name = m.group(0)
            lname = name.lower()
            j = m.end()
            if j < n and text[j] == ":":
                return self._named(lname, name, j + 1, pos)
            k = j
            while k < n and _is_space(text[k]):
                k += 1
            op = next((o for o in _OPS if text.startswith(o, k)), None)
            if op is not None and (k == j or lname in _CMP_NAMES):
                if lname not in _CMP_NAMES:
                    raise QueryError("'%s' cannot be compared" % name, pos)
                return self._comparison(lname, k + len(op), op, pos)
        end = self._run(i)
        word = text[i:end]
        self.i = end
        if word.lower() in _KEYWORDS:
            return ("KW", word.lower(), pos)
        return ("TERM", self._text_term(word), pos)

    def _named(self, lname, name, vstart, pos):
        text, n = self.text, self.n
        if lname not in _TEXT_NAMES:
            if lname == "amount":
                raise QueryError("'amount' needs a comparison operator, not ':'", pos)
            raise QueryError("unknown name '%s'" % name, pos)
        if vstart < n and text[vstart] == '"':
            value, end = self._quoted(vstart)
            if value == "":
                raise QueryError("empty quotes in %s: term" % lname, pos)
        else:
            end = self._run(vstart)
            value = text[vstart:end]
            if value == "":
                raise QueryError("missing value for %s:" % lname, pos)
        self.i = end
        return ("TERM", self._value_term(lname, value, pos), pos)

    def _comparison(self, lname, vstart, op, pos):
        text, n = self.text, self.n
        while vstart < n and _is_space(text[vstart]):
            vstart += 1
        end = self._run(vstart)
        value = text[vstart:end]
        if value == "":
            raise QueryError("missing value after %s%s" % (lname, op), pos)
        self.i = end
        if lname == "date":
            try:
                day = parse_date(value)
            except DateError:
                raise QueryError("invalid date '%s'" % value, pos) from None
            return ("TERM", _Func(lambda tx, p: _compare(op, tx.date, day)), pos)
        m = _AMOUNT_RE.fullmatch(value)
        code = m.group(2) if m else None
        if not m or (code and (not re.fullmatch(r"[A-Z]{3}", code) or code not in CURRENCIES)):
            raise QueryError("invalid amount '%s'" % value, pos)
        number = Fraction(m.group(1))

        def amount_test(tx, p):
            v = _posting_value(p)
            if v is None:
                return False
            if code and p.amount.currency != code:
                return False
            return _compare(op, v, number)

        return ("TERM", _Func(amount_test), pos)

    def _text_term(self, value):
        needle = value.lower()
        return _Func(lambda tx, p: _contains(tx.payee, needle) or _contains(tx.narration, needle))

    def _value_term(self, lname, value, pos):
        if lname in ("payee", "narration"):
            needle = value.lower()
            return _Func(lambda tx, p: _contains(getattr(tx, lname), needle))
        if lname == "tag":
            tag = value.lower()
            return _Func(lambda tx, p: tag in tuple(tx.tags or ()))
        if lname == "date":
            try:
                period = Period.parse(value)
            except DateError:
                raise QueryError("invalid period '%s'" % value, pos) from None
            return _Func(lambda tx, p: period.start <= tx.date <= period.end)
        if lname == "flag":
            if value not in ("*", "!"):
                raise QueryError("invalid flag '%s': expected * or !" % value, pos)
            return _Func(lambda tx, p: tx.flag == value)
        if lname == "id":
            if not re.fullmatch(r"[0-9]+", value):
                raise QueryError("invalid id '%s': digits only" % value, pos)
            wanted = int(value)
            return _Func(lambda tx, p: tx.id is not None and not isinstance(tx.id, bool)
                         and tx.id == wanted)
        # account
        parts = _split_pattern(value)
        if parts is None:
            raise QueryError("invalid account pattern '%s'" % value, pos)
        if self.chart is not None:
            if not any(_account_matches(parts, a.path) for a in self.chart.accounts()):
                raise QueryError("no account matches account:%s" % value, pos)
        return _Func(lambda tx, p: _account_matches(parts, getattr(p, "account", None)))


# -- parser --------------------------------------------------------------

class _Parser:
    def __init__(self, text, chart):
        self.lexer = _Lexer(text, chart)
        self.tok = self.lexer.next()

    def advance(self):
        tok = self.tok
        self.tok = self.lexer.next()
        return tok

    def parse(self):
        node = self.or_expr()
        kind, _, pos = self.tok
        if kind == "RP":
            raise QueryError("')' without a matching '('", pos)
        return node

    def or_expr(self):
        node = self.and_expr()
        while self.tok[0] == "KW" and self.tok[1] == "or":
            self.advance()
            node = _Or(node, self.and_expr())
        return node

    def and_expr(self):
        node = self.not_expr()
        while True:
            kind, value, _ = self.tok
            if kind == "KW" and value == "and":
                self.advance()
            elif not (kind in ("TERM", "LP") or (kind == "KW" and value == "not")):
                return node
            node = _And(node, self.not_expr())

    def not_expr(self):
        if self.tok[0] == "KW" and self.tok[1] == "not":
            self.advance()
            return _Not(self.not_expr())
        return self.primary()

    def primary(self):
        kind, value, pos = self.tok
        if kind == "TERM":
            self.advance()
            return value
        if kind == "LP":
            self.advance()
            node = self.or_expr()
            if self.tok[0] != "RP":
                raise QueryError("'(' is never closed", pos)
            self.advance()
            return node
        if kind == "END":
            raise QueryError("expected a term but the query ends", pos)
        what = "')'" if kind == "RP" else "'%s'" % value
        raise QueryError("expected a term, found %s" % what, pos)


# -- public --------------------------------------------------------------

class Query:
    """A parsed query; use ``matches``, ``matching_postings`` or ``select``."""

    def __init__(self, text, chart=None):
        if not isinstance(text, str):
            raise QueryError("query must be text, got %r" % (text,), 1)
        self.text = text
        if text.strip(" \t") == "":
            self._root = None
        else:
            self._root = _Parser(text, chart).parse()

    @property
    def is_empty(self):
        return self._root is None

    def __repr__(self):
        return "Query(%r)" % (self.text,)

    def __eq__(self, other):
        if not isinstance(other, Query):
            return NotImplemented
        return self.text == other.text

    def __hash__(self):
        return hash(self.text)

    def matching_postings(self, tx):
        postings = list(tx.postings)
        if self._root is None:
            return postings
        return [p for p in postings if self._root.eval(tx, p)]

    def matches(self, tx):
        if self._root is None:
            return True
        return any(self._root.eval(tx, p) for p in tx.postings)


def parse_query(text, chart=None):
    return Query(text, chart)


def select(transactions, q):
    if not isinstance(q, Query):
        q = parse_query(q)
    return [tx for tx in transactions if q.matches(tx)]

