        value = text[vstart:end]
        if value == "":
            raise QueryError("missing value after %s%s" % (lname, op), pos)
        self.i = end
        if lname == "date":
            try:
                day = parse_date(value)
            except DateError:
                raise QueryError("invalid date '%s'" % value, pos) from None
            return ("TERM", _Func(lambda tx, p: _compare(op, tx.date, day)), pos)
        m = _AMOUNT_RE.fullmatch(value)
        code = m.group(2) if m else None
        if not m or (code and (not re.fullmatch(r"[A-Z]{3}", code) or code not in CURRENCIES)):
            raise QueryError("invalid amount '%s'" % value, pos)
        number = Fraction(m.group(1))

        def amount_test(tx, p):
            v = _posting_value(p)
            if v is None:
                return False
            if code and p.amount.currency != code:
                return False
            return _compare(op, v, number)

        return ("TERM", _Func(amount_test), pos)

    def _text_term(self, value):
        needle = value.lower()
        return _Func(lambda tx, p: _contains(tx.payee, needle) or _contains(tx.narration, needle))

    def _value_term(self, lname, value, pos):
        if lname in ("payee", "narration"):
            needle = value.lower()
            return _Func(lambda tx, p: _contains(getattr(tx, lname), needle))
        if lname == "tag":
            tag = value.lower()
            return _Func(lambda tx, p: tag in tuple(tx.tags or ()))
        if lname == "date":
            try:
                period = Period.parse(value)
            except DateError:
                raise QueryError("invalid period '%s'" % value, pos) from None
            return _Func(lambda tx, p: period.start <= tx.date <= period.end)
        if lname == "flag":
            if value not in ("*", "!"):
                raise QueryError("invalid flag '%s': expected * or !" % value, pos)
            return _Func(lambda tx, p: tx.flag == value)
        if lname == "id":
            if not re.fullmatch(r"[0-9]+", value):
                raise QueryError("invalid id '%s': digits only" % value, pos)
            wanted = int(value)
            return _Func(lambda tx, p: tx.id is not None and not isinstance(tx.id, bool)
                         and tx.id == wanted)
        # account
        parts = _split_pattern(value)
        if parts is None:
            raise QueryError("invalid account pattern '%s'" % value, pos)
        if self.chart is not None:
            if not any(_account_matches(parts, a.path) for a in self.chart.accounts()):
                raise QueryError("no account matches account:%s" % value, pos)
        return _Func(lambda tx, p: _account_matches(parts, getattr(p, "account", None)))


# -- parser --------------------------------------------------------------

class _Parser:
    def __init__(self, text, chart):
        self.lexer = _Lexer(text, chart)
        self.tok = self.lexer.next()

    def advance(self):
        tok = self.tok
        self.tok = self.lexer.next()
        return tok

    def parse(self):
        node = self.or_expr()
        kind, _, pos = self.tok
        if kind == "RP":
            raise QueryError("')' without a matching '('", pos)
        return node

    def or_expr(self):
        node = self.and_expr()
        while self.tok[0] == "KW" and self.tok[1] == "or":
            self.advance()
            node = _Or(node, self.and_expr())
        return node

    def and_expr(self):
        node = self.not_expr()
        while True:
            kind, value, _ = self.tok
            if kind == "KW" and value == "and":
                self.advance()
            elif not (kind in ("TERM", "LP") or (kind == "KW" and value == "not")):
                return node
            node = _And(node, self.not_expr())

    def not_expr(self):
        if self.tok[0] == "KW" and self.tok[1] == "not":
            self.advance()
            return _Not(self.not_expr())
        return self.primary()

    def primary(self):
        kind, value, pos = self.tok
        if kind == "TERM":
            self.advance()
            return value
        if kind == "LP":
            self.advance()
            node = self.or_expr()
            if self.tok[0] != "RP":
                raise QueryError("'(' is never closed", pos)
            self.advance()
            return node
        if kind == "END":
            raise QueryError("expected a term but the query ends", pos)
        what = "')'" if kind == "RP" else "'%s'" % value
        raise QueryError("expected a term, found %s" % what, pos)


# -- public --------------------------------------------------------------

class Query:
    """A parsed query; use ``matches``, ``matching_postings`` or ``select``."""

    def __init__(self, text, chart=None):
        if not isinstance(text, str):
            raise QueryError("query must be text, got %r" % (text,), 1)
        self.text = text
        if text.strip(" \t") == "":
            self._root = None
        else:
            self._root = _Parser(text, chart).parse()

    @property
    def is_empty(self):
        return self._root is None

    def __repr__(self):
        return "Query(%r)" % (self.text,)

    def __eq__(self, other):
        if not isinstance(other, Query):
            return NotImplemented
        return self.text == other.text

    def __hash__(self):
        return hash(self.text)

    def matching_postings(self, tx):
        postings = list(tx.postings)
        if self._root is None:
            return postings
        return [p for p in postings if self._root.eval(tx, p)]

    def matches(self, tx):
        if self._root is None:
            return True
        return any(self._root.eval(tx, p) for p in tx.postings)


def parse_query(text, chart=None):
    return Query(text, chart)


def select(transactions, q):
    if not isinstance(q, Query):
        q = parse_query(q)
    return [tx for tx in transactions if q.matches(tx)]

